import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.hwbV7reR.js";const c=JSON.parse('{"title":"Обслуживание самостоятельного оркестратора","description":"","frontmatter":{},"headers":[],"relativePath":"operations.md","filePath":"operations.md","lastUpdated":1791695579000}'),h={name:"operations.md"};function n(l,s,p,r,k,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="обслуживание-самостоятельного-оркестратора" tabindex="-1">Обслуживание самостоятельного оркестратора <a class="header-anchor" href="#обслуживание-самостоятельного-оркестратора" aria-label="Permalink to &quot;Обслуживание самостоятельного оркестратора&quot;">​</a></h1><p>Для новой установки используйте <a href="./quickstart.html">быстрый старт</a>. Управление узлами доступно через локальный CLI и явно включённый режим <a href="./panel.html#управление">панели</a>; старый <code>admin_token_file</code> игнорируется. Параметры <code>nodes</code> нужны лишь для импорта прежней установки.</p><h1 id="эксплуатация" tabindex="-1">Эксплуатация <a class="header-anchor" href="#эксплуатация" aria-label="Permalink to &quot;Эксплуатация&quot;">​</a></h1><h2 id="размещение" tabindex="-1">Размещение <a class="header-anchor" href="#размещение" aria-label="Permalink to &quot;Размещение&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Путь</th><th>Содержимое</th></tr></thead><tbody><tr><td><code>/opt/vpn-orchestrator/releases/vVERSION-COMMIT/</code></td><td>Неизменяемый релиз со своей <code>.venv</code></td></tr><tr><td><code>/opt/vpn-orchestrator/current</code></td><td>Символическая ссылка на рабочий релиз</td></tr><tr><td><code>/etc/vpn-orchestrator/settings.json</code></td><td>Начальные настройки узлов, не из Git</td></tr><tr><td><code>/etc/vpn-orchestrator/*.token</code></td><td>Отдельные ключи, права 0600</td></tr><tr><td><code>/var/lib/vpn-orchestrator/assignments.sqlite3</code></td><td>Журнал назначений и переключений</td></tr><tr><td><code>/var/backups/undercore-orchestrator-COMMIT/</code></td><td>Приватный снимок перед обновлением</td></tr></tbody></table><p>Сервис работает от <code>vpn-orchestrator</code>, API слушает только loopback:8792. Настройки и ключи должны читаться этим пользователем; каталог состояния — 0700, SQLite — 0600. Код принадлежит root и недоступен сервису для записи.</p><p>Пример без настоящих адресов: <a href="https://github.com/UndercoreCo/orchestrator/blob/main/config/settings.example.json" target="_blank" rel="noreferrer">settings.example.json</a>. <code>schema_version</code> — версия настроек, <code>id</code> и <code>server_id</code> узла стабильны. <code>active</code> допускает новые назначения, <code>draining</code> обслуживает существующие, <code>disabled</code> исключает узел из обслуживания. Отключение узла в настройках не отзывает уже выданные peer на сервере. Не удалять записи узлов, на которые ссылается журнал. <code>check-config</code> проверяет также незавершённые цели переключений.</p><h2 id="команды" tabindex="-1">Команды <a class="header-anchor" href="#команды" aria-label="Permalink to &quot;Команды&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-config</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --probe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nodes</span></span></code></pre></div><p><code>--probe</code> выполняет только проверку health/идентичности узлов. Обычный <code>health</code> проверяет процесс оркестратора. Структурная проверка примера не требует ключей:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/settings.example.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --structure-only</span></span></code></pre></div><p>Примеры управления (фиктивные идентификаторы; реальные команды изменяют доступ):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-example-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MacBook</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expires-at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2027-01-01T00:00:00.000Z</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-example-01</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-example-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --expires-at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2027-02-01T00:00:00.000Z</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> renewal-example-01</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-example-01</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-example-01</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> recover</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CONNECTION_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device-example-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --revision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orchestratorctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reconcile</span></span></code></pre></div><p>CLI не проверяет оплату: это инструмент доверенного оператора. Вывод ограничен метаданными; приватный конфигурационный документ не печатается. <code>reconcile</code> продолжает уже начатые переключения, может вызвать мутации на узлах. Обычно его запускает <code>vpn-orchestrator-recovery.timer</code> каждые 30 секунд после завершения прохода.</p><h2 id="первыи-запуск-на-новом-сервере" tabindex="-1">Первый запуск на новом сервере <a class="header-anchor" href="#первыи-запуск-на-новом-сервере" aria-label="Permalink to &quot;Первый запуск на новом сервере&quot;">​</a></h2><p>Используйте <a href="./quickstart.html#установка-службы">установку службы</a>: scripts/install.py проверяет релиз, создаёт пользователя, каталоги и systemd units. Установщик не перезаписывает существующую установку и не добавляет VPN-узлы. После установки запустите службу, зарегистрируйте подготовленный агент и проверьте идентичность. Для обновления существующей службы применяется отдельный updater ниже.</p><h2 id="выпуск-и-обновление" tabindex="-1">Выпуск и обновление <a class="header-anchor" href="#выпуск-и-обновление" aria-label="Permalink to &quot;Выпуск и обновление&quot;">​</a></h2><ol><li>Изменить код и <code>VERSION</code>, выполнить тесты. Закоммитить и отправить в main.</li><li>Создать тег точно <code>vVERSION</code>, отправить его. GitHub Actions повторно проверит тесты/контракт и опубликует архив плюс <code>SHA256SUMS</code> в GitHub Releases.</li><li>На компьютере оператора с <code>gh</code>, SSH-доступом root и доверенным host key:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/deploy.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.3.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> root@YOUR_SERVER</span></span></code></pre></div><p>Первый перенос существующего сервиса без release manifest требует дополнительно <code>--adopt-existing</code>. Для обычных следующих релизов флаг не нужен. GitHub-токен остаётся на компьютере оператора. Новый релиз не разворачивается от произвольного push: явная команда выбирает точную проверенную версию.</p><p>Перед обновлением завершите отдельно запущенные процессы панели (особенно <code>--manage</code>) и команды изменения через CLI. Updater управляет только штатными API/recovery/leases units; произвольный процесс панели он не останавливает. Панель запускайте снова из нового <code>current</code> после успешного обновления.</p><p>Updater проверяет SHA256, список/типы файлов, версию, конфигурацию и отсутствие неявной миграции SQLite на копии. Устанавливает зависимости в отдельную <code>.venv</code> до остановки API. Затем приостанавливает обработчик, снимает согласованную копию журнала, меняет ссылку/units и проверяет health новой версии. Настройки и рабочий SQLite не заменяются; сайты и VPN-агенты не перезапускаются.</p><p>При ошибке после переключения возвращаются старые код/units и запуск сервиса. Живой журнал <strong>не откатывается</strong>: он может содержать уже выполненные операции. Версия 0.2 добавляет таблицы leases/cache/retired bindings, не изменяя существующие назначения и переключения. Иные изменения этих данных/схем отклоняются на копии. После включения leases допустим только lease-aware rollback; см. <a href="./node-agent.html#короткие-разрешения-и-отказ-контроллера">ограничения leases</a>.</p><p><code>SIGTERM</code>/разрыв SSH обрабатываются для попытки отката; сбой питания или <code>SIGKILL</code> невозможно гарантированно обработать. Тогда оператор сверяет <code>current</code>, units, health и приватный снимок. Никогда не заменять рабочую SQLite старой копией без сверки реальных peer на узлах. Повтор незавершённой установки в уже созданный каталог намеренно запрещён: сначала проверить результат предыдущей попытки.</p><h2 id="резервирование-и-наблюдение" tabindex="-1">Резервирование и наблюдение <a class="header-anchor" href="#резервирование-и-наблюдение" aria-label="Permalink to &quot;Резервирование и наблюдение&quot;">​</a></h2><p>SQLite снимать через online backup API либо при остановленных API и worker. Сохранять отдельно настройки/ключи, units, release manifest и сведения о версии. Копии содержат служебные секреты: ограничить права, шифровать и выносить с машины. Из архивов кода исключать <code>.venv</code>, <code>venv</code>, <code>.git</code>, <code>__pycache__</code>. Предрелизная копия на том же диске не заменяет независимый backup.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-timers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator-recovery.timer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator-recovery.service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;1 hour ago&#39;</span></span></code></pre></div><p>Access log приложения выключен. Не включать отладочное логирование заголовков и тел конфигурационных ответов в прокси/HTTP-клиентах. Текущий updater рассчитан на один экземпляр оркестратора и локальную SQLite; несколько активных копий с разными журналами нельзя запускать как балансируемые реплики.</p><h2 id="проверяемая-резервная-копия-и-восстановление" tabindex="-1">Проверяемая резервная копия и восстановление <a class="header-anchor" href="#проверяемая-резервная-копия-и-восстановление" aria-label="Permalink to &quot;Проверяемая резервная копия и восстановление&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/vpn-orchestrator/settings.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/backups/snapshot-01</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/backups/snapshot-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /secure/recovery/candidate-01</span></span></code></pre></div><p>Команды выполняются пользователем, имеющим доступ к приватным файлам службы. <code>backup</code> снимает согласованную SQLite-копию, берёт реестр именно из неё, сохраняет нужные служебные ключи и настройки. Файлы имеют права 0600, каталог — 0700. <code>backup.json</code> записывается последним: содержит версию программы/схемы, время и SHA256 каждого файла. Это контроль целостности, не цифровая подпись и не шифрование. Копии без манифеста (включая старый формат backup) команда restore не принимает.</p><p><code>restore backup</code> проверяет комплект и контрольные суммы, восстанавливает в <strong>новый</strong> каталог, переносит пути ключей и проверяет/мигрирует локальную базу. Он не пишет по старым путям из backup, не заменяет рабочую базу, не вызывает VPN API и не запускает службы. Повтор поверх существующего каталога запрещён. Статус <code>restored_for_review</code> означает подготовленную копию, а не восстановленную работу VPN.</p><p>В <code>state/.restore-review-required</code> создаётся блокировка: обычный запуск с этими настройками завершается <code>restore_review_required</code>. До активации оператор должен:</p><ol><li>Остановить прежний controller и оба worker/timer; исключить второй активный экземпляр.</li><li>Сверить назначения, незавершённые операции, запреты и leases с реальными агентами. После снимка могли быть созданы/отозваны peer; SHA256 и integrity_check этого не определяют.</li><li>Разобрать расхождения. Старые controller/sequence нельзя просто обнулить; неизвестный результат мутации нельзя разрешать повторной выдачей на другом сервере.</li><li>Только после сверки удалить <code>.restore-review-required</code> в подготовленном каталоге, проверить настройки, права и пути, затем отдельно выполнить переключение установки.</li></ol><p>Автоматическая сверка после потери актуального журнала пока не реализована. Маркер сознательно не имеет команды «пропустить проверку». Незавершённый каталог после ошибки остаётся для диагностики и не считается готовой копией.</p><h2 id="локальныи-реестр-узлов" tabindex="-1">Локальный реестр узлов <a class="header-anchor" href="#локальныи-реестр-узлов" aria-label="Permalink to &quot;Локальный реестр узлов&quot;">​</a></h2><p>После первого запуска определения <code>nodes</code> импортируются в SQLite. Далее общий слой команд CLI/панели меняет реестр; JSON не перезаписывает его. После ротации ключей bootstrap-файлы больше не нужны, если на них не ссылается действующий реестр. Старый <code>admin_token_file</code> игнорируется, сайт не имеет полномочий управления.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> servers</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NODE_ID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NODE_ID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/change.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vpn-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> undercore-orchestrator</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NODE_ID</span></span></code></pre></div><p>Файл изменения приватный (0600), содержит полный набор полей и expected_revision. Restore отзывает старые перенесённые доступы до открытия узла. Backup должен включать журнал, актуальные секреты, настройки и deployment units. Команда backup собирает журнал/настройки/секреты; версию релиза и units сохраняйте вместе с ними.</p><p>Структура событий, корреляция запросов и защищённый endpoint Prometheus описаны в <a href="./observability.html">диагностике и метриках</a>. Сбор метрик не опрашивает VPN-узлы.</p><h2 id="просмотр-состояния-в-браузере" tabindex="-1">Просмотр состояния в браузере <a class="header-anchor" href="#просмотр-состояния-в-браузере" aria-label="Permalink to &quot;Просмотр состояния в браузере&quot;">​</a></h2><p>Команда <code>panel</code> запускает самостоятельную панель без изменения VPN-узлов. <a href="./panel.html">Отдельный ключ, SSH-доступ и ограничения</a>.</p>`,42)])])}const F=i(h,[["render",n]]);export{c as __pageData,F as default};
